def test_mutant_kill_allow_extra_args_false():
    @click.group()
    def cli():
        pass

    @cli.command()
    @click.argument('arg')
    def subcmd(arg):
        pass

    runner = CliRunner()
    # This triggers the _resolve_context path with nested commands
    # and extra args that should be allowed when allow_extra_args=True
    result = runner.invoke(cli, ['subcmd', 'value', 'extra1', 'extra2'])
    # With allow_extra_args=True, extra args are accepted and stored in protected_args
    # With allow_extra_args=False, extra args cause an error
    assert result.exit_code == 0
    assert 'extra1' in result.output or result.output == ''

