from jinja2.lexer import TokenStream

class BadExtension:
    identifier = "bad_extension"
    priority = 0

    def __init__(self, environment):
        self.environment = environment

    def preprocess(self, source, name, filename=None):
        return source

    def filter_stream(self, stream):
        # Return a plain list instead of TokenStream
        return list(stream)

def test_mutation_kill_tokenstream_arg():
    env = Environment(extensions=[BadExtension])
    with pytest.raises(TypeError):
        env.parse("{{ 1 + 1 }}")

