import click
from click.testing import CliRunner

def test_mutation_arg_kill():
    @click.group(chain=True)
    def cli():
        pass

    @cli.command()
    @click.option('--name', required=True)
    def sub1(name):
        click.echo(f"sub1:{name}")

    @cli.command()
    @click.option('--value', required=True)
    def sub2(value):
        click.echo(f"sub2:{value}")

    runner = CliRunner()
    # Chain two commands that both require options
    # The original code passes the command name to make_context, so the
    # option parsing works correctly for each chained command.
    # The mutation passes None, which will cause the option to be
    # misinterpreted or cause an error.
    result = runner.invoke(cli, ["sub1", "--name", "hello", "sub2", "--value", "world"], prog_name="cli")
    assert result.exit_code == 0
    assert result.output == "sub1:hello\nsub2:world\n"
